// ── Primitives: assignment copies the VALUE ───────────────────
let a = 10;
let b = a;    // b gets an independent copy of the number 10
b = 99;
console.log(a); // 10 — completely unaffected

// ── Objects: assignment copies the REFERENCE ──────────────────
const user1 = { name: 'Alice', score: 42 };
const user2 = user1;   // user2 holds the SAME heap address as user1
user2.score = 100;
console.log(user1.score); // 100 — same heap object!

// ── Reference equality vs. structural equality ────────────────
const objA = { x: 1 };
const objB = { x: 1 };
const objC = objA;
console.log(objA === objB); // false — different heap addresses
console.log(objA === objC); // true  — same heap address

// ── Passing objects to functions ──────────────────────────────
function addBonus(player) {
  player.score += 50;  // mutates the caller's object!
}
const p = { name: 'Bob', score: 200 };
addBonus(p);
console.log(p.score); // 250 — caller sees the mutation

// ── Strings look mutable but are immutable primitives ─────────
let s1 = 'hello';
let s2 = s1;
s2 = s2.toUpperCase(); // creates a NEW string; does not mutate s1
console.log(s1); // 'hello' — unchanged

// ── Shallow clone: nested objects remain shared ───────────────
const original = {
  id: 1,
  address: { city: 'Tokyo', zip: '100-0001' }
};

const shallow = { ...original };
shallow.id = 999;             // primitive — independent ✓
shallow.address.city = 'Osaka'; // reference — shared ✗

console.log(original.id);             // 1    — unaffected (primitive copied)
console.log(original.address.city);   // 'Osaka' — oops! shared reference

// ── Deep clone: fully independent tree ───────────────────────
const deep = structuredClone(original);
deep.address.city = 'Kyoto';
console.log(original.address.city);   // 'Osaka' — truly independent now

// ── JSON trick: works but has limitations ─────────────────────
const jsonClone = JSON.parse(JSON.stringify(original));
jsonClone.address.city = 'Nagoya';
console.log(original.address.city);   // 'Osaka' — also works

// ── JSON clone drops undefined and converts dates ─────────────
const tricky = { a: undefined, b: new Date() };
const jsonTricky = JSON.parse(JSON.stringify(tricky));
console.log(jsonTricky);  // { b: '2024-...' }  — 'a' lost, Date is string now

sections.content:
Closures are where stack-vs-heap rules intersect in a surprising way. Normally, a function's local variables live on the stack frame and are destroyed when the function returns. But what if an inner function references a local variable from an outer function, and that inner function is passed out and called later? The outer frame is gone, but the inner function still needs that variable.

Languages with first-class functions solve this by keeping captured variables somewhere longer-lived than the frame. In V8 the decision is made at **parse time**: any variable that an inner function references is allocated from the start in a heap object called a **Context**, and every closure created in that scope holds a pointer to it. (Lua takes a different route: captured variables — **upvalues** — live on the stack until the enclosing function returns and are then "closed" by copying them to the heap.)

A V8 subtlety worth knowing: closures created in the same scope **share one Context**. If any one of them references a large variable, that variable is kept alive for as long as *any* closure from that scope is alive — even closures that never use it.

This means closures can accidentally keep large objects alive longer than you expect. A classic example: an event listener closure that captures a huge `data` array will prevent that array from being garbage collected as long as the event listener remains registered, even if nothing else references `data`. Removing event listeners when they are no longer needed is not just good practice — it is memory hygiene.

Closures are also why JavaScript can implement private state without classes:

```javascript
function makeCounter() {
  let count = 0;       // captured on the heap
  return {
    increment() { count++; },
    value()     { return count; }
  };
}
const c = makeCounter();
c.increment(); c.increment();
console.log(c.value()); // 2 — count persists on the heap
```

`count` survives because the returned object's methods hold a reference to it via their closure. The stack frame for `makeCounter()` is gone, but the heap keeps `count` alive as long as the returned object exists.

