// ── Closure capturing a heap variable ────────────────────────
function makeCounter(start = 0) {
  let count = start;  // 'count' escapes to the heap (captured by closures)
  return {
    increment() { count += 1; },
    decrement() { count -= 1; },
    reset()     { count = start; },
    value()     { return count; }
  };
}

const c = makeCounter(10);
c.increment();
c.increment();
c.decrement();
console.log(c.value()); // 11

// ── Memory-leak pattern: closure capturing too much ───────────
function registerHandler(bigData) {
  const summary = bigData.length; // only need the length
  // Bad: captures the entire bigData array through the closure
  document.addEventListener('click', () => {
    console.log('data length was', bigData.length);
  });
  // bigData cannot be GC'd as long as the listener is registered!
}

// Better: extract only what you need, avoid capturing the full object
function registerHandlerFixed(bigData) {
  const summary = bigData.length;
  document.addEventListener('click', () => {
    console.log('data length was', summary); // bigData can now be GC'd
  });
}

// ── Stack overflow from deep recursion ────────────────────────
function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);  // each call pushes a new stack frame
}
console.log(factorial(10));   // 3628800 — fine
// factorial(100000);          // RangeError: Maximum call stack size exceeded

// Iterative version avoids stack growth (BigInt keeps the result exact):
function factorialIter(n) {
  let result = 1n;
  for (let i = 2n; i <= BigInt(n); i++) result *= i;
  return result;
}
console.log(factorialIter(1000).toString().length); // 2568 digits — O(1) stack space
// (With plain numbers, anything above 170! overflows to Infinity.)

sections.content:
JavaScript is technically **pass-by-value** — always. But for reference types, the value being passed is *the reference itself* (the memory address). This nuance trips up many developers.

When you pass a primitive, the function receives a copy of the number/string/boolean. When you pass an object, the function receives a copy of the reference (address) — so the function can mutate the heap object the reference points to, but it cannot make the caller's variable point to a different object.

```javascript
function tryToReplace(obj) {
  obj = { brand: 'new object' };  // reassigns local copy of reference
}                                  // caller's reference unchanged

const original = { value: 1 };
tryToReplace(original);
console.log(original); // { value: 1 } — caller unaffected
```

```javascript
function mutate(obj) {
  obj.value = 99;  // mutates the shared heap object
}

const item = { value: 1 };
mutate(item);
console.log(item.value); // 99 — caller sees the change
```

This is sometimes called **pass-by-sharing** or **call-by-object-sharing** to distinguish it from true pass-by-reference (where the caller's variable itself could be repointed). Languages like C++ have actual pass-by-reference (`void f(int& x)`) which can rebind the caller's variable; JavaScript does not.
